@require_GET
@login_required
def reporte_movimientos_kardex(request):
    producto_talla_id = request.GET.get('producto_talla_id')
    fecha_inicio = request.GET.get('fecha_inicio')
    fecha_fin = request.GET.get('fecha_fin')
    page = int(request.GET.get('page', 1))
    page_size = min(int(request.GET.get('page_size', 100)), 500)
    if not producto_talla_id:
        return JsonResponse({'success': False, 'error': 'ID de producto requerido'}, status=400)
    producto_talla = get_object_or_404(
        Producto_Talla.objects.select_related('producto'), id=producto_talla_id
    )
    # Scoping: el kardex de un SKU solo es visible para usuarios con acceso
    # a la sucursal dueña del producto (mismo criterio que ver_dte).
    from app.utils_permisos import puede_ver_sucursal
    if not puede_ver_sucursal(request.user, producto_talla.producto.sucursal_id):
        return JsonResponse(
            {'success': False, 'error': 'No tiene acceso al kardex de esta sucursal.'},
            status=403,
        )
    # --- Apertura sintética de la migración (ver REF_SALDO_INICIAL_SINTETICO) ---
    # La carga inicial de la migración Laravel entró como INGRESO_INICIAL con
    # referencia MIGRACION_LARAVEL (~2026-01-22) ENCIMA del kardex legacy ya
    # migrado (referencias MIG:<id>): sumarla tal cual duplica el stock (mismo
    # fenómeno que corrigen _saldos_periodo / _mapas_movimientos_sucursal en
    # views_modulo_reportes.py).
    #
    # Criterio del saldo corrido (medido contra prod, ver Fase B):
    #   1. DEFAULT: la apertura NO aporta al saldo (queda absorbida en el
    #      kardex legacy que la precede). Con eso 20/20 SKUs de la muestra
    #      cuadran saldo final == Producto_Talla.stock.
    #   2. RE-ANCLA (excepción): si excluyéndola el saldo final de TODA la
    #      historia NO cuadra con el stock, pero tratando la apertura como
    #      FOTO (saldo re-anclado a su valor + movimientos posteriores) SÍ
    #      cuadra, entonces la apertura es el dato autoritativo (SKU
    #      solo-apertura o kardex legacy incompleto, p.ej. PT 214822) y su
    #      fila aporta ``delta = apertura - acumulado_previo``.
    #   3. Si ninguna variante cuadra (drift real kardex-vs-stock, p.ej.
    #      PT 362970 con +34 de drift pre-existente), rige el default.
    # La decisión usa la historia COMPLETA del SKU (es una propiedad del SKU,
    # no del rango de fechas consultado).
    from app.constants_kardex import REF_SALDO_INICIAL_SINTETICO
    es_apertura_q = Q(
        concepto='INGRESO_INICIAL',
        referencia_externa=REF_SALDO_INICIAL_SINTETICO,
    )
    base_completado = Movimientos_Producto.objects.filter(
        ProductoTalla=producto_talla, estado='COMPLETADO'
    )
    primera_apertura_hist = (
        base_completado.filter(es_apertura_q)
        .order_by('fecha', 'hora', 'id')
        .values('id', 'fecha', 'hora')
        .first()
    )
    reanclar = False
    if primera_apertura_hist:
        apertura_hist = base_completado.filter(es_apertura_q).aggregate(
            s=Sum('cantidad'))['s'] or 0
        total_hist = base_completado.aggregate(s=Sum('cantidad'))['s'] or 0
        despues_de_apertura_q = (
            Q(fecha__gt=primera_apertura_hist['fecha'])
            | Q(fecha=primera_apertura_hist['fecha'],
                hora__gt=primera_apertura_hist['hora'])
            | Q(fecha=primera_apertura_hist['fecha'],
                hora=primera_apertura_hist['hora'],
                id__gt=primera_apertura_hist['id'])
        )
        post_hist = base_completado.filter(despues_de_apertura_q).exclude(
            concepto='INGRESO_INICIAL',
            referencia_externa=REF_SALDO_INICIAL_SINTETICO,
        ).aggregate(s=Sum('cantidad'))['s'] or 0
        stock_actual = producto_talla.stock or 0
        final_excluyendo = total_hist - apertura_hist
        final_reanclando = apertura_hist + post_hist
        reanclar = (final_excluyendo != stock_actual
                    and final_reanclando == stock_actual)
    # select_related sobre dte y ticket: el bucle de abajo los lee para armar la
    # referencia, y sin esto son 2 queries por fila (hasta 1.000 por pagina).
    movimientos = Movimientos_Producto.objects.filter(
        ProductoTalla=producto_talla
    ).select_related('sucursal_destino', 'dte', 'ticket').order_by('fecha', 'hora', 'id')
    if fecha_inicio:
        from django.utils.dateparse import parse_date
        movimientos = movimientos.filter(fecha__gte=parse_date(fecha_inicio))
    if fecha_fin:
        from django.utils.dateparse import parse_date
        movimientos = movimientos.filter(fecha__lte=parse_date(fecha_fin))
    total_count = movimientos.count()
    offset = (page - 1) * page_size
    # El saldo se acumula en SQL sobre TODO el rango filtrado, no sobre la pagina:
    # antes se reiniciaba en 0 en cada pagina y el saldo era falso desde la 2 en
    # adelante. La window function se evalua antes del LIMIT/OFFSET.
    # Al saldo solo aportan los movimientos COMPLETADOS (un CANCELADO/PENDIENTE
    # se lista pero no mueve el acumulado). La apertura sintética aporta 0 o,
    # si el SKU re-ancla, su primera fila aporta el delta de re-anclaje
    # calculado DENTRO del rango filtrado (el acumulado también es relativo al
    # rango). Las filas excluidas siguen mostrando su entrada/salida; el saldo
    # simplemente no salta en ellas.
    condiciones_aporte = [When(~Q(estado='COMPLETADO'), then=Value(0))]
    if reanclar:
        primera_apertura = (
            movimientos.filter(es_apertura_q, estado='COMPLETADO')
            .order_by('fecha', 'hora', 'id')
            .values('id', 'fecha', 'hora')
            .first()
        )
        if primera_apertura:
            apertura_rango = movimientos.filter(
                es_apertura_q, estado='COMPLETADO'
            ).aggregate(s=Sum('cantidad'))['s'] or 0
            antes_de_apertura_q = (
                Q(fecha__lt=primera_apertura['fecha'])
                | Q(fecha=primera_apertura['fecha'],
                    hora__lt=primera_apertura['hora'])
                | Q(fecha=primera_apertura['fecha'],
                    hora=primera_apertura['hora'],
                    id__lt=primera_apertura['id'])
            )
            acumulado_previo = movimientos.filter(
                antes_de_apertura_q, estado='COMPLETADO'
            ).exclude(
                concepto='INGRESO_INICIAL',
                referencia_externa=REF_SALDO_INICIAL_SINTETICO,
            ).aggregate(s=Sum('cantidad'))['s'] or 0
            condiciones_aporte.append(When(
                id=primera_apertura['id'],
                then=Value(apertura_rango - acumulado_previo),
            ))
    condiciones_aporte.append(When(es_apertura_q, then=Value(0)))
    movimientos = movimientos.annotate(
        aporte_saldo=Case(
            *condiciones_aporte,
            default=F('cantidad'),
            output_field=IntegerField(),
        ),
    ).annotate(
        saldo_acumulado=Window(
            expression=Sum('aporte_saldo'),
            order_by=[F('fecha').asc(), F('hora').asc(), F('id').asc()],
        )
    )
    movimientos = movimientos[offset:offset+page_size]
    kardex = []
    for m in movimientos:
        saldo = m.saldo_acumulado or 0
        es_apertura = (
            m.concepto == 'INGRESO_INICIAL'
            and m.referencia_externa == REF_SALDO_INICIAL_SINTETICO
        )
        # Enriquecer referencia
        referencia = ''
        if m.dte:
            referencia = f"{m.dte.tipo_documento} {m.dte.numero_documento}"
        elif m.ticket:
            referencia = f"Ticket {m.ticket.correlativo}"
        elif m.referencia_externa:
            referencia = m.referencia_externa
        elif m.sucursal_destino:
            referencia = f"Destino: {m.sucursal_destino.alias}"
        kardex.append({
            'fecha': m.fecha.strftime('%Y-%m-%d'),
            'hora': m.hora.strftime('%H:%M'),
            'concepto': m.concepto,
            'tipo_movimiento': m.tipo_movimiento,
            'entrada': m.cantidad if m.cantidad > 0 else 0,
            'salida': abs(m.cantidad) if m.cantidad < 0 else 0,
            'saldo': saldo,
            'costo': m.costo,
            'precio': m.precio,
            'responsable': m.responsable,
            'referencia': referencia,
            'sucursal_destino': m.sucursal_destino.alias if m.sucursal_destino else '',
            'estado': m.estado,
            # Marca para la UI: fila de la apertura sintética de la migración.
            # Si no está anclada, su entrada se muestra pero el saldo no salta.
            'es_apertura': es_apertura,
        })
    return JsonResponse({
        'success': True,
        'items': kardex,
        'pagination': {
            'page': page,
            'page_size': page_size,
            'total_count': total_count,
            'total_pages': (total_count + page_size - 1) // page_size,
            'has_next': offset + page_size < total_count,
            'has_previous': page > 1
        }
    })
@require_GET
@login_required
def reporte_kardex_agrupado(request):
    """
    Genera un kardex agrupado por producto (sin mostrar tallas ni SKU)
    """
    producto_id = request.GET.get('producto_id')
    fecha_inicio = request.GET.get('fecha_inicio')
    fecha_fin = request.GET.get('fecha_fin')
    page = int(request.GET.get('page', 1))
    page_size = min(int(request.GET.get('page_size', 100)), 500)
    
    if not producto_id:
        return JsonResponse({'success': False, 'error': 'ID de producto requerido'}, status=400)

    producto = get_object_or_404(Producto, id=producto_id)

    # Scoping: mismo criterio que reporte_movimientos_kardex.
    from app.utils_permisos import puede_ver_sucursal
    if not puede_ver_sucursal(request.user, producto.sucursal_id):
        return JsonResponse(
            {'success': False, 'error': 'No tiene acceso al kardex de esta sucursal.'},
            status=403,
        )

    # --- Apertura sintética de la migración (ver REF_SALDO_INICIAL_SINTETICO) ---
    # Mismo criterio que reporte_movimientos_kardex, aplicado POR TALLA:
    # DEFAULT la apertura de la migración (INGRESO_INICIAL + referencia
    # MIGRACION_LARAVEL) no aporta al saldo (duplicaría el kardex legacy
    # migrado); EXCEPCIÓN, si para una talla excluir la apertura no cuadra con
    # Producto_Talla.stock pero tratarla como FOTO (re-anclar el acumulado a
    # su valor) sí cuadra, esa talla re-ancla y la fila de apertura aporta
    # ``apertura - acumulado previo de la talla``. La decisión usa la historia
    # completa (no el rango filtrado).
    from app.constants_kardex import REF_SALDO_INICIAL_SINTETICO
    es_apertura_q = Q(
        concepto='INGRESO_INICIAL',
        referencia_externa=REF_SALDO_INICIAL_SINTETICO,
    )
    apertura_por_talla = {
        fila['ProductoTalla_id']: fila['apertura'] or 0
        for fila in Movimientos_Producto.objects.filter(
            ProductoTalla__producto=producto, estado='COMPLETADO'
        ).filter(es_apertura_q).values('ProductoTalla_id').annotate(
            apertura=Sum('cantidad')
        )
    }
    tallas_reancla = set()
    if apertura_por_talla:
        stock_por_talla = dict(
            Producto_Talla.objects.filter(producto=producto)
            .values_list('id', 'stock')
        )
        # Pasada liviana sobre la historia completa para partir cada talla en
        # pre-apertura / post-apertura y evaluar ambas variantes del final.
        historia = Movimientos_Producto.objects.filter(
            ProductoTalla__producto=producto, estado='COMPLETADO'
        ).order_by('fecha', 'hora', 'id').values_list(
            'ProductoTalla_id', 'cantidad', 'concepto', 'referencia_externa'
        )
        acum_tallas = {}  # talla_id -> [pre, post, vio_apertura]
        for talla_id, cantidad, concepto, ref in historia.iterator(chunk_size=2000):
            datos = acum_tallas.setdefault(talla_id, [0, 0, False])
            if (concepto == 'INGRESO_INICIAL'
                    and ref == REF_SALDO_INICIAL_SINTETICO):
                datos[2] = True
            elif datos[2]:
                datos[1] += cantidad
            else:
                datos[0] += cantidad
        for talla_id, (pre, post, vio_apertura) in acum_tallas.items():
            if not vio_apertura:
                continue
            stock_talla = stock_por_talla.get(talla_id) or 0
            if (pre + post != stock_talla
                    and apertura_por_talla.get(talla_id, 0) + post == stock_talla):
                tallas_reancla.add(talla_id)
    acumulado_por_talla = {}
    tallas_reancladas = set()

    # Obtener todos los movimientos del producto (todas las tallas). El 'id'
    # desempata timestamps iguales para que el re-anclaje sea determinista.
    movimientos = Movimientos_Producto.objects.filter(
        ProductoTalla__producto=producto
    ).select_related('ProductoTalla', 'dte', 'ticket', 'sucursal_destino').order_by('fecha', 'hora', 'id')

    if fecha_inicio:
        from django.utils.dateparse import parse_date
        movimientos = movimientos.filter(fecha__gte=parse_date(fecha_inicio))
    if fecha_fin:
        from django.utils.dateparse import parse_date
        movimientos = movimientos.filter(fecha__lte=parse_date(fecha_fin))

    # Agrupar movimientos por fecha y concepto
    from collections import defaultdict
    movimientos_agrupados = defaultdict(lambda: {
        'fecha': None,
        'hora': None,
        'concepto': None,
        'tipo_movimiento': None,
        'cantidad_total': 0,
        'aporte_saldo': 0,
        'es_apertura': False,
        'costo_promedio': 0,
        'precio_promedio': 0,
        'responsable': None,
        'referencia': None,
        'sucursal_destino': '',
        'movimientos_detalle': []
    })
    
    for m in movimientos:
        # Crear clave única por fecha + concepto + responsable
        key = f"{m.fecha}_{m.concepto}_{m.responsable}_{m.sucursal_destino_id or ''}"
        
        grupo = movimientos_agrupados[key]
        if not grupo['fecha']:
            grupo['fecha'] = m.fecha
            grupo['hora'] = m.hora
            grupo['concepto'] = m.concepto
            grupo['tipo_movimiento'] = m.tipo_movimiento
            grupo['responsable'] = m.responsable
            grupo['sucursal_destino'] = m.sucursal_destino.alias if m.sucursal_destino else ''
            
            # Enriquecer referencia
            referencia = m.referencia_externa or ''
            if m.dte:
                tipo_doc = m.dte.tipo_documento
                if tipo_doc == 'GUIA' and m.dte.tipo_transaccion == 'VENTA':
                    referencia = f"Guía {m.dte.numero_documento} - Despacho"
                else:
                    referencia = f"{tipo_doc} {m.dte.numero_documento}"
            elif m.ticket:
                referencia = f"Ticket {m.ticket.correlativo}"
            grupo['referencia'] = referencia
        
        # Sumar cantidades. La fila muestra el movimiento completo
        # (cantidad_total) pero al saldo solo aportan los COMPLETADOS; la
        # apertura sintética aporta su delta de re-anclaje por talla.
        es_apertura_mov = (
            m.concepto == 'INGRESO_INICIAL'
            and m.referencia_externa == REF_SALDO_INICIAL_SINTETICO
        )
        if es_apertura_mov:
            grupo['es_apertura'] = True
        grupo['cantidad_total'] += m.cantidad
        if m.estado == 'COMPLETADO':
            talla_id = m.ProductoTalla_id
            if es_apertura_mov:
                if (talla_id in tallas_reancla
                        and talla_id not in tallas_reancladas):
                    tallas_reancladas.add(talla_id)
                    aporte = (apertura_por_talla.get(talla_id, 0)
                              - acumulado_por_talla.get(talla_id, 0))
                else:
                    aporte = 0
            else:
                aporte = m.cantidad
            grupo['aporte_saldo'] += aporte
            acumulado_por_talla[talla_id] = (
                acumulado_por_talla.get(talla_id, 0) + aporte
            )
        grupo['movimientos_detalle'].append({
            'talla': m.ProductoTalla.talla,
            'sku': m.ProductoTalla.sku,
            'cantidad': m.cantidad
        })

    # Convertir a lista y calcular saldo acumulado
    kardex_agrupado = []
    saldo_acumulado = 0

    for grupo in sorted(movimientos_agrupados.values(), key=lambda x: (x['fecha'], x['hora'])):
        saldo_acumulado += grupo['aporte_saldo']

        kardex_agrupado.append({
            'fecha': grupo['fecha'].strftime('%Y-%m-%d'),
            'hora': grupo['hora'].strftime('%H:%M') if grupo['hora'] else '',
            'concepto': grupo['concepto'],
            'tipo_movimiento': grupo['tipo_movimiento'],
            'entrada': grupo['cantidad_total'] if grupo['cantidad_total'] > 0 else 0,
            'salida': abs(grupo['cantidad_total']) if grupo['cantidad_total'] < 0 else 0,
            'saldo': saldo_acumulado,
            'responsable': grupo['responsable'],
            'referencia': grupo['referencia'],
            'sucursal_destino': grupo['sucursal_destino'],
            # Marca para la UI: grupo con apertura sintética de la migración.
            'es_apertura': grupo['es_apertura'],
            'detalle_tallas': grupo['movimientos_detalle']  # Para mostrar en tooltip o modal
        })
    
    # Paginación
    total_count = len(kardex_agrupado)
    offset = (page - 1) * page_size
    kardex_paginado = kardex_agrupado[offset:offset+page_size]
    
    return JsonResponse({
        'success': True,
        'producto': {
            'id': producto.id,
            'articulo': producto.articulo,
            'descripcion': producto.descripcion,
            'stock_total': Producto_Talla.objects.filter(producto=producto).aggregate(total_stock=Sum('stock'))['total_stock'] or 0
        },
        'items': kardex_paginado,
        'pagination': {
            'page': page,
            'page_size': page_size,
            'total_count': total_count,
            'total_pages': (total_count + page_size - 1) // page_size,
            'has_next': offset + page_size < total_count,
            'has_previous': page > 1
        }
    })

@require_GET
@login_required
def obtener_productos_base(request):
    """
    Obtiene productos base (sin tallas) para el selector del kardex agrupado
    """
    q = request.GET.get('q', '').strip()
    page = int(request.GET.get('page', 1))
    page_size = min(int(request.GET.get('page_size', 20)), 100)
    sucursal_id = request.session.get('idSucursalActual')
    
    # select_related sobre los atributos: el bucle de abajo lee .valor de los tres
    # y sin esto son 3 consultas por fila (hasta 300 por página).
    productos = Producto.objects.select_related('atributo1', 'atributo2', 'atributo3')
    if sucursal_id:
        productos = productos.filter(sucursal_id=sucursal_id)

    if q:
        productos = productos.filter(
            Q(articulo__icontains=q) |
            Q(descripcion__icontains=q) |
            Q(atributo1__valor__icontains=q) |
            Q(atributo2__valor__icontains=q) |
            Q(atributo3__valor__icontains=q)
        )
    
    total_count = productos.count()
    offset = (page - 1) * page_size
    productos = productos.order_by('articulo')[offset:offset+page_size]
    
    def limpiar_prefijo(valor):
        if not valor:
            return ''
        for prefijo in ['Marca:', 'Color:', 'Género:']:
            if valor.startswith(prefijo):
                return valor[len(prefijo):].strip()
        return valor.strip()
    
    results = []
    for prod in productos:
        marca = limpiar_prefijo(prod.atributo1.valor if prod.atributo1 else '')
        color = limpiar_prefijo(prod.atributo2.valor if prod.atributo2 else '')
        genero = limpiar_prefijo(prod.atributo3.valor if prod.atributo3 else '')
        
        text = f"{prod.articulo} - {prod.descripcion}"
        if marca:
            text += f" | Marca: {marca}"
        if color:
            text += f" | Color: {color}"
        if genero:
            text += f" | Género: {genero}"
        
        results.append({
            'id': prod.id,
            'text': text,
            'articulo': prod.articulo,
            'descripcion': prod.descripcion,
            'marca': marca,
            'color': color,
            'genero': genero
        })
    
    return JsonResponse({
        'results': results,
        'pagination': {
            'more': offset + page_size < total_count
        }
    })

@login_required
def verGestionCompras(request):
    # Esta vista solo maneja GET requests para mostrar la página
    # Los POST requests para crear compras se manejan en la vista crear_compra
    empresas = Empresa.objects.filter(esProveedor=True).order_by('nombre')  # Solo proveedores
    
    # Obtener IDs de atributos para el modal Agregar Producto Manual
    try:
        marca = Productos_Atributos.objects.filter(nombre__iexact='Marca').first()
        color = Productos_Atributos.objects.filter(nombre__iexact='Color').first()
        genero = Productos_Atributos.objects.filter(nombre__iexact='Sexo').first()
        if not genero:
            genero = Productos_Atributos.objects.filter(nombre__iexact='Género').first()
        if not genero:
            genero = Productos_Atributos.objects.filter(nombre__icontains='gener').first()
    except Exception:
        marca = color = genero = None
    
    sucursal_id = request.session.get('idSucursalActual')
    puede_eliminar_compra = PermisoRol.tiene_permiso(
        request.user, 'gestion_compras', 'puede_eliminar', sucursal_id=sucursal_id
    )

    # Sucursales disponibles para el selector opcional de importación y la
    # asignación masiva en Recepción de Productos.
    sucursales_disponibles = list(
        Sucursal.objects.all().order_by('alias').values('id', 'alias')
    )

    context = {
        'empresas': empresas,
        'id_atributo_marca': marca.id if marca else 0,
        'id_atributo_color': color.id if color else 0,
        'id_atributo_genero': genero.id if genero else 0,
        'puede_eliminar_compra': puede_eliminar_compra,
        'sucursales_disponibles': sucursales_disponibles,
    }
    return render(request, 'vistas/modulo_compras/gestionCompras.html', context)
 
@login_required
def verGestionProducto(request):
    """
    Vista para gestión de productos con inicialización automática de atributos
    """
    atributos = {}

    def _leer_atributos():
        """Los 5 atributos del modal en UNA consulta (antes: 4 consultas
        separadas contra una BD con RTT de ~200 ms)."""
        buscados = ('marca', 'color', 'sexo', 'género', 'genero', 'especialidad')
        por_nombre = {}
        for a in Productos_Atributos.objects.all().only('id', 'nombre'):
            por_nombre[(a.nombre or '').strip().lower()] = a
        faltan = [n for n in ('marca', 'color') if n not in por_nombre]
        if faltan:
            raise Productos_Atributos.DoesNotExist(', '.join(faltan))
        return por_nombre

    try:
        atributos = _leer_atributos()
        marca = atributos.get('marca')
        color = atributos.get('color')
        # IMPORTANTE: Usar "Sexo" que es el atributo real usado en productos (ID 3)
        # "Género" (ID 4) tiene valores diferentes y no coincide
        genero = (atributos.get('sexo') or atributos.get('género')
                  or atributos.get('genero'))

    except Productos_Atributos.DoesNotExist:
        # Si no existen los atributos, ejecutar inicialización automática
        from django.core.management import call_command
        from django.contrib import messages
        
        try:
            call_command('inicializar_atributos')
            messages.success(request, 'Atributos básicos inicializados correctamente.')
            
            # Intentar obtener los atributos nuevamente
            atributos = _leer_atributos()
            marca = atributos.get('marca')
            color = atributos.get('color')
            genero = (atributos.get('sexo') or atributos.get('género')
                      or atributos.get('genero'))
            
        except Exception as e:
            messages.error(request, f'Error al inicializar atributos: {str(e)}')
            # Valores por defecto en caso de error
            atributos = {}
            marca = color = genero = None

    # Atributo transversal "Especialidad" (deporte/uso, multi-etiqueta) de la
    # taxonomía v1.2. Se pasa su id para que el modal Crear Manual cargue sus
    # opciones con el mismo mecanismo select2-atributo que Marca/Color/Género.
    especialidad = atributos.get('especialidad')

    context = {
        'id_atributo_marca': marca.id if marca else 0,
        'id_atributo_color': color.id if color else 0,
        'id_atributo_genero': genero.id if genero else 0,
        'id_atributo_especialidad': especialidad.id if especialidad else 0,
    }

    return render(request, 'vistas/modulo_existencias/verGestionProductos.html', context)
