@login_required
@solo_administrador
def debug_user_empresas(request):
    """Vista temporal para debug de empresas del usuario"""
    try:
        debug_data = {
            'usuario_actual': str(request.user),
            'empresas_disponibles': [],
            'sucursales_disponibles': [],
            'relaciones_empresa_user': [],
            'problema_detectado': None
        }
        
        # Obtener todas las empresas del usuario
        empresas_usuario = EmpresaUser.objects.filter(
            user=request.user
        ).select_related('empresa', 'sucursal')
        
        for eu in empresas_usuario:
            debug_data['relaciones_empresa_user'].append({
                'empresa_id': eu.empresa.id,
                'empresa_nombre': eu.empresa.nombre,
                'empresa_rut': eu.empresa.rut,
                'sucursal_id': eu.sucursal.id if eu.sucursal else None,
                'sucursal_alias': eu.sucursal.alias if eu.sucursal else None,
                'status': eu.status,
                'active': eu.active
            })
            
            # Agregar empresa a la lista si no está
            empresa_info = {
                'id': eu.empresa.id,
                'nombre': eu.empresa.nombre,
                'rut': eu.empresa.rut
            }
            if empresa_info not in debug_data['empresas_disponibles']:
                debug_data['empresas_disponibles'].append(empresa_info)
        
        # Obtener todas las sucursales de las empresas del usuario
        empresas_ids = [eu.empresa.id for eu in empresas_usuario if eu.status]
        sucursales = Sucursal.objects.filter(
            empresa_id__in=empresas_ids
        ).select_related('empresa')
        
        # Detectar sucursales mal asignadas
        problemas_sucursales = []
        for sucursal in sucursales:
            debug_data['sucursales_disponibles'].append({
                'id': sucursal.id,
                'alias': sucursal.alias,
                'direccion': sucursal.direccion,
                'empresa_id': sucursal.empresa.id,
                'empresa_nombre': sucursal.empresa.nombre,
                'empresa_rut': sucursal.empresa.rut
            })
            
            # Detectar si hay sucursales NICK en empresa Paola
            if 'NICK' in sucursal.alias and 'Paola' in sucursal.empresa.nombre:
                problemas_sucursales.append(f"Sucursal {sucursal.alias} está en {sucursal.empresa.nombre} pero debería estar en Importadora Nicole Andrea")
        
        if problemas_sucursales:
            debug_data['problema_detectado'] = {
                'tipo': 'sucursales_mal_asignadas',
                'detalles': problemas_sucursales,
                'solucion': 'Corregir las asignaciones de empresa en las sucursales NICK1 y NICK2'
            }
        
        # Información de sesión actual
        debug_data['sesion_actual'] = {
            'idSucursalActual': request.session.get('idSucursalActual'),
            'idEmpresaActual': request.session.get('idEmpresaActual'),
            'alias': request.session.get('alias'),
            'nombreEmpresaActual': request.session.get('nombreEmpresaActual')
        }
        
        # Simular filtro para facturas (otras empresas)
        empresa_actual_id = request.session.get('idEmpresaActual')
        if empresa_actual_id:
            otras_empresas = [emp for emp in debug_data['empresas_disponibles'] if emp['id'] != empresa_actual_id]
            debug_data['simulacion_factura_interna'] = {
                'empresa_actual_id': empresa_actual_id,
                'otras_empresas_disponibles': otras_empresas,
                'sucursales_otras_empresas': [
                    suc for suc in debug_data['sucursales_disponibles'] 
                    if suc['empresa_id'] != empresa_actual_id
                ]
            }
        
        return JsonResponse(debug_data, json_dumps_params={'indent': 2})
        
    except Exception as e:
        return JsonResponse({
            'error': str(e),
            'tipo_error': type(e).__name__
        }, status=500)

@require_GET
@login_required
def empresas_clientes(request):
    """
    Obtener lista de empresas que pueden ser receptores de DTE (clientes)
    Incluye todas las empresas (proveedores y no proveedores pueden ser clientes)
    """
    try:
        # Obtener TODAS las empresas (una empresa puede ser proveedor Y cliente)
        clientes = Empresa.objects.all().order_by('nombre')
        
        data = []
        for cliente in clientes:
            # Indicar si también es proveedor para referencia
            tipo = "Proveedor" if cliente.esProveedor else "Cliente"
            data.append({
                'id': cliente.id,
                'nombre': cliente.nombre,
                'rut': cliente.rut,
                'nombre_fantasia': cliente.nombre_fantasia,
                'razon_social': cliente.razon_social,
                'giro': cliente.giro or '',
                'direccion': cliente.direccion or '',
                'comuna': cliente.comuna or '',
                'ciudad': cliente.ciudad or '',
                'acteco': cliente.acteco or '',
                'es_proveedor': cliente.esProveedor,
                'tipo': tipo,
            })
        
        return JsonResponse(data, safe=False)
        
    except Exception as e:
        return JsonResponse({
            'success': False,
            'error': f'Error al obtener clientes: {str(e)}'
        }, status=500)

@require_POST
@login_required
def crear_empresa_rapida(request):
    """
    Crear una empresa de forma rápida desde el modal de emisión DTE.
    Solo campos esenciales para poder emitir documentos.
    """
    try:
        data = json.loads(request.body)

        rut = data.get('rut', '').strip()
        razon_social = data.get('razon_social', '').strip()
        giro = data.get('giro', '').strip()
        direccion = data.get('direccion', '').strip()
        comuna = data.get('comuna', '').strip()
        ciudad = data.get('ciudad', '').strip()

        if not all([rut, razon_social, giro, direccion, comuna, ciudad]):
            return JsonResponse({
                'success': False,
                'error': 'Campos obligatorios: RUT, Razón Social, Giro, Dirección, Comuna, Ciudad'
            }, status=400)

        if Empresa.objects.filter(rut=rut).exists():
            empresa_existente = Empresa.objects.filter(rut=rut).first()
            return JsonResponse({
                'success': True,
                'empresa_id': empresa_existente.id,
                'mensaje': f'La empresa con RUT {rut} ya existe. Se seleccionó automáticamente.'
            })

        nombre_fantasia = data.get('nombre_fantasia', '').strip() or razon_social
        email = data.get('email', '').strip()
        telefono = data.get('telefono', '').strip()
        acteco = data.get('acteco', '').strip()

        empresa = Empresa.objects.create(
            nombre=razon_social,
            rut=rut,
            razon_social=razon_social,
            nombre_fantasia=nombre_fantasia,
            giro=giro,
            direccion=direccion,
            comuna=comuna,
            ciudad=ciudad,
            esProveedor=False,
            correoVendedor=email or '',
            correoIntercambio=email or '',
            correoAdministrador=email or '',
            acteco=acteco or '',
            telefono=telefono or '',
            email=email or None,
            tipo_empresa='CLIENTE',
            activo=True,
        )

        return JsonResponse({
            'success': True,
            'empresa_id': empresa.id,
            'mensaje': f'Empresa {razon_social} creada exitosamente.'
        })

    except Exception as e:
        return JsonResponse({
            'success': False,
            'error': f'Error al crear empresa: {str(e)}'
        }, status=500)


@require_GET
@login_required
def obtener_marcas(request):
    """
    Obtener lista de marcas disponibles (atributo1)
    """
    try:
        # Obtener el atributo "Marca" 
        atributo_marca = Productos_Atributos.objects.filter(nombre__icontains='marca').first()
        
        if not atributo_marca:
            return JsonResponse([])
        
        marcas = AtributoOpcion.objects.filter(atributo=atributo_marca).order_by('valor')
        
        data = []
        for marca in marcas:
            data.append({
                'id': marca.id,
                'valor': marca.valor
            })
        
        return JsonResponse(data, safe=False)
        
    except Exception as e:
        return JsonResponse({
            'success': False,
            'error': f'Error al obtener marcas: {str(e)}'
        }, status=500)

@require_GET
@login_required
def obtener_categorias(request):
    """
    Obtener lista de categorías disponibles (árbol v1.2).

    Devuelve [{id, nombre}] con los padres primero ("X (toda la rama)") y sus
    hijas etiquetadas "Padre › Hija"; filtrar por el id de un padre incluye la
    rama completa en los reportes (ver _expandir_categoria_ids). Las categorías
    deprecadas por la recategorización (prefijo _ZZ_) se ocultan.
    """
    try:
        categorias = list(
            Categoria.objects.exclude(nombre__startswith='_ZZ_')
            .order_by('nombre').values('id', 'nombre', 'padre_id')
        )
        hijas_por_padre = {}
        for c in categorias:
            if c['padre_id']:
                hijas_por_padre.setdefault(c['padre_id'], []).append(c)

        data = []
        for p in (c for c in categorias if not c['padre_id']):
            hijas = hijas_por_padre.get(p['id'], [])
            if hijas:
                data.append({'id': p['id'], 'nombre': f"{p['nombre']} (toda la rama)"})
                data.extend(
                    {'id': h['id'], 'nombre': f"{p['nombre']} › {h['nombre']}"}
                    for h in hijas
                )
            else:
                # Plana antigua aún con productos: visible pero marcada
                data.append({'id': p['id'], 'nombre': f"{p['nombre']} (sin recategorizar)"})

        return JsonResponse(data, safe=False)
        
    except Exception as e:
        return JsonResponse({
            'success': False,
            'error': f'Error al obtener categorías: {str(e)}'
        }, status=500)

@login_required
def buscar_productos_bodega(request):
    """
    Buscar productos en bodega con filtros y paginación
    ✅ OPTIMIZADO para 1M+ registros - Usa paginación a nivel de BD
    """
    try:
        from django.db.models import Sum, Case, When, Value, IntegerField, Prefetch
        from django.db.models.functions import Coalesce
        
        # Obtener parámetros de filtro
        search = request.GET.get('search', '').strip()
        filtro_tabla = request.GET.get('filtro_tabla', '').strip()
        marca_id = request.GET.get('marca', '') or None
        categoria_id = request.GET.get('categoria', '') or None
        tipo_talla = request.GET.get('tipo_talla', '') or None
        solo_con_stock = request.GET.get('incluir_sin_stock', 'false').lower() != 'true'
        page = int(request.GET.get('page', 1))
        page_size = min(int(request.GET.get('page_size', 20)), 50)
        
        # Obtener sucursal actual
        sucursal_id = request.session.get('idSucursalActual') or request.session.get('sucursalActual')
        
        if not sucursal_id:
            return JsonResponse({
                'success': False,
                'error': 'No hay sucursal activa en la sesión'
            }, status=400)
        
        # ═══════════════════════════════════════════════════════════════
        # PASO 1: Query base optimizada con anotación de stock
        # ═══════════════════════════════════════════════════════════════
        productos_query = Producto.objects.filter(
            sucursal_id=sucursal_id
        ).select_related(
            'categoria', 'atributo1', 'atributo2', 'atributo3'
        )
        
        # Filtros aplicados a nivel de BD (rápido).
        # OPTIMIZACIÓN: si search es numérico, hacer match exacto contra
        # Producto_Talla.sku (BigInteger) en vez de __icontains. __icontains
        # sobre BigInt fuerza CAST a string y full table scan; el = usa índice.
        if search:
            search_strip = search.strip()
            filtros = (
                Q(articulo__icontains=search) |
                Q(descripcion__icontains=search)
            )
            if search_strip.isdigit():
                filtros = filtros | Q(producto_talla__sku=int(search_strip))
            # Si no es numérico no se toca el SKU: comparar texto contra un campo
            # que solo contiene dígitos no puede devolver nada, y costaba un CAST
            # más el scan completo del join en cada búsqueda.
            productos_query = productos_query.filter(filtros)

        if categoria_id:
            productos_query = productos_query.filter(categoria_id=categoria_id)
        
        if marca_id:
            productos_query = productos_query.filter(atributo1_id=marca_id)
        
        if tipo_talla:
            productos_query = productos_query.filter(tipo_talla=tipo_talla)
        
        # Anotar stock usando el campo directo (para paginación rápida)
        productos_query = productos_query.annotate(
            stock_anotado=Coalesce(Sum('producto_talla__stock'), Value(0))
        ).distinct()
        
        # Filtrar por stock si es necesario
        if solo_con_stock:
            productos_query = productos_query.filter(stock_anotado__gt=0)
        
        # Ordenar por artículo para consistencia
        productos_query = productos_query.order_by('articulo')
        
        # ═══════════════════════════════════════════════════════════════
        # PASO 2: Contar total y aplicar paginación a nivel de BD
        # ═══════════════════════════════════════════════════════════════
        total_count = productos_query.count()
        total_pages = (total_count + page_size - 1) // page_size if total_count > 0 else 1
        
        # Paginación a nivel de BD (CRÍTICO para rendimiento)
        start = (page - 1) * page_size
        productos_paginados = list(productos_query[start:start + page_size])
        
        if not productos_paginados:
            return JsonResponse({
                'success': True,
                'productos': [],
                'pagination': {
                    'page': page,
                    'page_size': page_size,
                    'total_count': total_count,
                    'total_pages': total_pages,
                    'has_next': False,
                    'has_previous': page > 1
                }
            })
        
        # ═══════════════════════════════════════════════════════════════
        # PASO 3: Obtener IDs de productos paginados para consulta batch
        # ═══════════════════════════════════════════════════════════════
        producto_ids = [p.id for p in productos_paginados]
        
        # Obtener todas las tallas de los productos paginados en UNA sola consulta
        tallas_query = Producto_Talla.objects.filter(
            producto_id__in=producto_ids
        ).select_related('producto')
        
        if solo_con_stock:
            tallas_query = tallas_query.filter(stock__gt=0)
        
        # ═══════════════════════════════════════════════════════════════
        # PASO 4: Construir respuesta usando stock directo de Producto_Talla
        # ═══════════════════════════════════════════════════════════════
        # NOTA: Usamos talla.stock directamente porque es el valor sincronizado
        # desde MySQL (producción). No recalculamos con movimientos.
        tallas_list = list(tallas_query)
        
        # Agrupar tallas por producto
        tallas_por_producto = {}
        for talla in tallas_list:
            if talla.producto_id not in tallas_por_producto:
                tallas_por_producto[talla.producto_id] = []
            
            # Usar stock directo de la tabla (sincronizado desde MySQL)
            # Solo mostrar stock si el producto pertenece a la sucursal actual
            if talla.producto.sucursal_id == sucursal_id:
                stock_calculado = max(0, talla.stock or 0)
            else:
                stock_calculado = 0
            
            tallas_por_producto[talla.producto_id].append({
                'id': talla.id,
                'talla': talla.talla,
                'stock': stock_calculado,
                'sku': talla.sku,
            })
        
        # ═══════════════════════════════════════════════════════════════
        # BATCH lookup de foto_portada_url para los articulos del page.
        # Una sola query a FotoPortadaArticulo (ya filtrada por activos +
        # principal). Preferencia: foto de la misma Empresa → fallback global
        # ordenado por prioridad.
        # ═══════════════════════════════════════════════════════════════
        from app.models import FotoPortadaArticulo
        articulos_page = {p.articulo for p in productos_paginados if p.articulo}
        empresa_id_actual = None
        try:
            empresa_id_actual = Sucursal.objects.values_list(
                'empresa_id', flat=True,
            ).get(id=sucursal_id)
        except Sucursal.DoesNotExist:
            pass

        fotos_qs = (
            FotoPortadaArticulo.objects
            .filter(articulo__in=articulos_page, es_principal=True, origen__activo=True)
            .select_related('origen')
            .values('articulo', 'url_foto', 'origen__empresa_id', 'origen__prioridad')
        )
        fotos_propias: dict = {}
        fotos_fallback: dict = {}
        for f in fotos_qs:
            if empresa_id_actual and f['origen__empresa_id'] == empresa_id_actual:
                fotos_propias[f['articulo']] = f['url_foto']
            existing = fotos_fallback.get(f['articulo'])
            if not existing or f['origen__prioridad'] > existing[1]:
                fotos_fallback[f['articulo']] = (f['url_foto'], f['origen__prioridad'])

        def _foto_url_local(articulo):
            if not articulo:
                return ''
            if articulo in fotos_propias:
                return fotos_propias[articulo]
            fb = fotos_fallback.get(articulo)
            return fb[0] if fb else ''

        # Construir respuesta final
        productos_data = []
        for producto in productos_paginados:
            tallas_data = tallas_por_producto.get(producto.id, [])

            # Filtrar tallas sin stock si es necesario
            if solo_con_stock:
                tallas_data = [t for t in tallas_data if t['stock'] > 0]

            if not tallas_data and solo_con_stock:
                continue

            stock_total = sum(t['stock'] for t in tallas_data)

            # Agregar precio a cada talla
            for talla in tallas_data:
                talla['precio_venta'] = float(producto.precioventa) if producto.precioventa else 0
                talla['sobreprecio'] = float(producto.sobreprecio) if producto.sobreprecio else 0
                talla['costo'] = float(producto.costo) if producto.costo else 0

            productos_data.append({
                'id': producto.id,
                'articulo': producto.articulo,
                'descripcion': producto.descripcion,
                'marca': producto.atributo1.valor if producto.atributo1 else '',
                'color': producto.atributo2.valor if producto.atributo2 else '',
                'categoria': producto.categoria.nombre if producto.categoria else '',
                'tipo_talla': producto.tipo_talla,
                'precio_venta': float(producto.precioventa) if producto.precioventa else 0,
                'sobreprecio': float(producto.sobreprecio) if producto.sobreprecio else 0,
                'costo': float(producto.costo) if producto.costo else 0,
                'stock_total': stock_total,
                'tallas_disponibles': [t['talla'] for t in tallas_data],
                'tallas_detalle': tallas_data,
                'tallas': tallas_data,
                'sucursal_id': producto.sucursal_id,
                'foto_portada_url': _foto_url_local(producto.articulo),
            })
        
        return JsonResponse({
            'success': True,
            'productos': productos_data,
            'pagination': {
                'page': page,
                'page_size': page_size,
                'total_count': total_count,
                'total_pages': total_pages,
                'has_next': page < total_pages,
                'has_previous': page > 1
            }
        })
        
    except json.JSONDecodeError as e:
        return JsonResponse({
            'success': False,
            'error': f'Datos JSON inválidos: {str(e)}'
        }, status=400)
    except Exception as e:
        # Log más detallado para debugging
        import logging
        logger = logging.getLogger(__name__)
        logger.error(f'Error en buscar_productos_bodega: {str(e)}', exc_info=True)
        
        return JsonResponse({
            'success': False,
            'error': f'Error al buscar productos: {str(e)}'
        }, status=500)


@require_GET
@login_required
def buscar_dte_referencia(request):
    """
    Buscar productos a partir de DTEs por referencia (número documento, emisor, SKU, etc.).
    Incluye facturas de compra y documentos recepcionados.
    Devuelve productos en el mismo formato que buscar_productos_bodega para reusar el frontend.
    """
    try:
        from django.db.models.functions import Coalesce

        search = request.GET.get('search', '').strip()
        if not search:
            return JsonResponse({'success': False, 'error': 'Ingrese un término de búsqueda'}, status=400)

        try:
            page = max(1, int(request.GET.get('page', 1)))
        except (TypeError, ValueError):
            page = 1
        try:
            page_size = min(max(1, int(request.GET.get('page_size', 10))), 50)
        except (TypeError, ValueError):
            page_size = 10

        sucursal_id = request.session.get('idSucursalActual') or request.session.get('sucursalActual')
        empresa_id = request.session.get('idEmpresaActual')
        if not sucursal_id or not empresa_id:
            return JsonResponse({'success': False, 'error': 'No hay sucursal/empresa activa en la sesión'}, status=400)

        try:
            sucursal_actual = Sucursal.objects.select_related('empresa').get(id=sucursal_id)
            empresa_actual = sucursal_actual.empresa
        except Sucursal.DoesNotExist:
            return JsonResponse({'success': False, 'error': 'Sucursal no encontrada'}, status=400)

        # Buscar DTEs recibidos: receptor = empresa actual, o COMPRA de la sucursal
        dte_query = Dte.objects.filter(
            Q(receptor=empresa_actual) | Q(tipo_transaccion='COMPRA', sucursal=sucursal_actual)
        ).filter(descartado=False)

        # `sku` es BigIntegerField: el __icontains forzaba CAST a texto sobre las
        # ~605.000 filas de Producto_Talla, dos veces (Dte_Productos y
        # Productos_Recepcionados) y con DISTINCT encima. Si el término es
        # numérico se busca exacto contra el índice; si no, el SKU no participa.
        search_strip = (search or '').strip()
        search_es_numerico = search_strip.isdigit()

        # Buscar por campos del DTE y por productos en Dte_Productos
        search_q_dte = (
            Q(numero_documento__icontains=search) |
            Q(emisor__nombre__icontains=search) |
            Q(emisor__rut__icontains=search) |
            Q(tipo_documento__icontains=search) |
            Q(responsable__icontains=search) |
            Q(dte_productos__productoTalla__producto__articulo__icontains=search) |
            Q(dte_productos__descripcion__icontains=search)
        )
        # Buscar tambien por productos en Productos_Recepcionados (compras)
        search_q_recepcion = (
            Q(numero_documento__icontains=search) |
            Q(emisor__nombre__icontains=search) |
            Q(emisor__rut__icontains=search) |
            Q(tipo_documento__icontains=search) |
            Q(responsable__icontains=search) |
            Q(recepciones__producto_talla__producto__articulo__icontains=search) |
            Q(recepciones__compra_producto_talla__compra_producto__nombre__icontains=search)
        )
        if search_es_numerico:
            search_q_dte = search_q_dte | Q(dte_productos__productoTalla__sku=int(search_strip))
            search_q_recepcion = search_q_recepcion | Q(recepciones__producto_talla__sku=int(search_strip))

        dte_ids = list(
            dte_query.filter(search_q_dte | search_q_recepcion)
            .distinct().order_by('-fecha_emision', '-id')
            .values_list('id', flat=True)[:30]
        )

        if not dte_ids:
            return JsonResponse({
                'success': True,
                'productos': [],
                'pagination': {'page': 1, 'page_size': page_size, 'total_count': 0, 'total_pages': 1,
                                'has_next': False, 'has_previous': False}
            })

        productos_map = {}
        suc_id_int = int(sucursal_id)

        def _add_to_map(prod, pt, dte_obj):
            if prod.id not in productos_map:
                productos_map[prod.id] = {
                    'producto': prod,
                    'tallas': {},
                    'dte_info': f"{dte_obj.tipo_documento} #{dte_obj.numero_documento}",
                }
            if pt.id not in productos_map[prod.id]['tallas']:
                stock_real = max(0, pt.stock or 0) if prod.sucursal_id == suc_id_int else 0
                productos_map[prod.id]['tallas'][pt.id] = {
                    'id': pt.id,
                    'talla': pt.talla,
                    'stock': stock_real,
                    'sku': pt.sku,
                    'precio_venta': float(prod.precioventa) if prod.precioventa else 0,
                    'sobreprecio': float(prod.sobreprecio) if prod.sobreprecio else 0,
                    'costo': float(prod.costo) if prod.costo else 0,
                }

        # 1) Productos desde Dte_Productos (ventas/traspasos)
        lineas = Dte_Productos.objects.filter(
            dte_id__in=dte_ids,
            productoTalla__isnull=False
        ).select_related(
            'productoTalla__producto__categoria',
            'productoTalla__producto__atributo1',
            'productoTalla__producto__atributo2',
            'productoTalla__producto__atributo3',
            'dte'
        )
        dte_ids_con_lineas = set()
        for linea in lineas:
            pt = linea.productoTalla
            prod = pt.producto
            if not prod:
                continue
            dte_ids_con_lineas.add(linea.dte_id)
            _add_to_map(prod, pt, linea.dte)

        # 2) Para DTEs sin Dte_Productos (compras), buscar en Productos_Recepcionados
        dte_ids_sin_lineas = [did for did in dte_ids if did not in dte_ids_con_lineas]
        if dte_ids_sin_lineas:
            recepciones = Productos_Recepcionados.objects.filter(
                dte_id__in=dte_ids_sin_lineas,
                producto_talla__isnull=False
            ).select_related(
                'producto_talla__producto__categoria',
                'producto_talla__producto__atributo1',
                'producto_talla__producto__atributo2',
                'producto_talla__producto__atributo3',
                'dte'
            )
            for rec in recepciones:
                pt = rec.producto_talla
                prod = pt.producto
                if not prod:
                    continue
                _add_to_map(prod, pt, rec.dte)

        # Construir respuesta en el mismo formato que buscar_productos_bodega
        productos_data = []
        for prod_id, data in productos_map.items():
            prod = data['producto']
            tallas_data = list(data['tallas'].values())
            stock_total = sum(t['stock'] for t in tallas_data)

            productos_data.append({
                'id': prod.id,
                'articulo': prod.articulo,
                'descripcion': prod.descripcion,
                'marca': prod.atributo1.valor if prod.atributo1 else '',
                'color': prod.atributo2.valor if prod.atributo2 else '',
                'categoria': prod.categoria.nombre if prod.categoria else '',
                'tipo_talla': prod.tipo_talla,
                'precio_venta': float(prod.precioventa) if prod.precioventa else 0,
                'sobreprecio': float(prod.sobreprecio) if prod.sobreprecio else 0,
                'costo': float(prod.costo) if prod.costo else 0,
                'stock_total': stock_total,
                'tallas_disponibles': [t['talla'] for t in tallas_data],
                'tallas_detalle': tallas_data,
                'tallas': tallas_data,
                'sucursal_id': prod.sucursal_id,
                'origen_dte': data['dte_info'],
            })

        # Orden estable (el iterado de Dte_Productos no tiene order_by, asi que
        # sin esto cada request podria entregar paginas inconsistentes)
        productos_data.sort(key=lambda p: ((p['articulo'] or ''), p['id']))

        total_count = len(productos_data)
        total_pages = (total_count + page_size - 1) // page_size if total_count > 0 else 1
        page = min(page, total_pages)
        start = (page - 1) * page_size

        return JsonResponse({
            'success': True,
            'productos': productos_data[start:start + page_size],
            'pagination': {
                'page': page,
                'page_size': page_size,
                'total_count': total_count,
                'total_pages': total_pages,
                'has_next': page < total_pages,
                'has_previous': page > 1,
            }
        })

    except Exception as e:
        import logging
        logging.getLogger(__name__).error(f'Error en buscar_dte_referencia: {e}', exc_info=True)
        return JsonResponse({'success': False, 'error': f'Error al buscar DTEs: {str(e)}'}, status=500)


@require_GET
@login_required
def obtener_sucursales(request):
    """
    Obtener lista de sucursales para despacho interno
    
    REGLAS DE NEGOCIO PARA DESPACHO INTERNO:
    =========================================
    1. Si la sucursal actual es EDEL o GILD:
       - Con GUÍA: Puede enviar a CUALQUIER sucursal de todas las empresas
       - Con FACTURA: Puede enviar a sucursales de OTRAS empresas (no la misma)
    
    2. Si la sucursal actual NO es EDEL ni GILD (ej: PAO1, NICK1, etc.):
       - Con GUÍA: Solo puede enviar a sucursales de la MISMA empresa (PAO1→PAO2, PAO3, etc.)
       - Con FACTURA: Solo puede enviar a sucursales de OTRAS empresas (para evitar auto-facturación)
    
    Parámetros:
    - filtro_tipo: 'guia_misma_empresa' | 'guia_todas' | 'factura_otras_empresas'
    """
    try:
        sucursal_actual_id = request.session.get('idSucursalActual')
        empresa_actual_id = request.session.get('idEmpresaActual')
        filtro_tipo = request.GET.get('filtro_tipo', 'guia_misma_empresa')
        
        logger.debug(
            "Despacho interno obtener_sucursales: usuario=%s sucursal_id=%s empresa_id=%s filtro_tipo=%s",
            request.user,
            sucursal_actual_id,
            empresa_actual_id,
            filtro_tipo,
        )
        
        if not empresa_actual_id:
            logger.warning("No hay empresa actual en sesion al obtener sucursales")
            return JsonResponse({
                'success': False,
                'error': 'No hay empresa actual en la sesión'
            }, status=400)
        
        # Obtener información de la empresa actual
        try:
            empresa_actual_obj = Empresa.objects.get(id=empresa_actual_id)
            rut_empresa_actual = empresa_actual_obj.rut
            logger.debug("Empresa actual para despacho: empresa_id=%s rut=%s", empresa_actual_id, rut_empresa_actual)
        except Empresa.DoesNotExist:
            logger.warning("Empresa actual no existe al obtener sucursales: empresa_id=%s", empresa_actual_id)
            return JsonResponse({
                'success': False,
                'error': f'Empresa con ID {empresa_actual_id} no encontrada'
            }, status=400)
        
        # Obtener todas las empresas del usuario
        todas_empresas_usuario = EmpresaUser.objects.filter(
            user=request.user,
            status=True
        ).values_list('empresa_id', flat=True)
        
        empresas_usuario_list = list(todas_empresas_usuario)
        logger.debug("Empresas del usuario para despacho: usuario=%s empresas=%s", request.user, empresas_usuario_list)
        
        # ═══════════════════════════════════════════════════════════════
        # APLICAR FILTRO SEGÚN TIPO DE DESPACHO
        # ═══════════════════════════════════════════════════════════════
        
        if filtro_tipo == 'guia_misma_empresa':
            # GUÍA para sucursales normales (no EDEL/GILD): SOLO misma empresa
            logger.debug("Filtro despacho guia misma empresa: empresa_id=%s", empresa_actual_id)
            empresas_filtro = [empresa_actual_id]
            excluir_mismo_rut = False
            
        elif filtro_tipo == 'guia_todas':
            # GUÍA para EDEL/GILD: TODAS las sucursales de todas las empresas del usuario
            logger.debug("Filtro despacho guia todas las empresas")
            empresas_filtro = empresas_usuario_list
            excluir_mismo_rut = False
            
        elif filtro_tipo == 'factura_otras_empresas':
            # FACTURA: Sucursales de OTRAS empresas (diferentes RUT para evitar auto-factura)
            # Se busca en TODAS las empresas del sistema, no solo las asignadas al usuario,
            # para que usuarios con una sola empresa asignada puedan facturar a otras.
            todas_las_empresas = list(Empresa.objects.filter(activo=True).values_list('id', flat=True))
            logger.debug("Filtro despacho factura otras empresas: empresas_activas=%s", todas_las_empresas)
            empresas_filtro = todas_las_empresas
            excluir_mismo_rut = True
            
        else:
            # Valor por defecto: igual que guia_misma_empresa
            logger.warning("Filtro de despacho desconocido; usando misma empresa: filtro_tipo=%s", filtro_tipo)
            empresas_filtro = [empresa_actual_id]
            excluir_mismo_rut = False
        
        # Obtener sucursales según el filtro, excluyendo la actual
        sucursales_query = Sucursal.objects.filter(
            empresa_id__in=empresas_filtro
        ).exclude(
            id=sucursal_actual_id  # Siempre excluir la sucursal actual
        ).select_related('empresa')
        
        # Si es FACTURA, excluir sucursales del mismo RUT (evitar auto-facturación)
        if excluir_mismo_rut and rut_empresa_actual:
            logger.debug("Aplicando filtro RUT distinto para despacho: rut=%s", rut_empresa_actual)
            sucursales_query = sucursales_query.exclude(empresa__rut=rut_empresa_actual)
        
        logger.debug("Sucursales encontradas para despacho: total=%s", sucursales_query.count())
        
        sucursales_list = []
        for sucursal in sucursales_query:
            sucursal_data = {
                'id': sucursal.id,
                'nombre': sucursal.alias,
                'direccion': sucursal.direccion,
                'empresa': sucursal.empresa.razon_social,
                'empresa_id': sucursal.empresa.id,
                'empresa_rut': sucursal.empresa.rut
            }
            sucursales_list.append(sucursal_data)
        
        # Resumen final
        resumen_tipo = {
            'guia_misma_empresa': 'GUÍA (misma empresa)',
            'guia_todas': 'GUÍA ESPECIAL (todas las empresas - EDEL/GILD)',
            'factura_otras_empresas': 'FACTURA (otras empresas)'
        }
        logger.debug(
            "Resumen sucursales despacho: tipo=%s total=%s",
            resumen_tipo.get(filtro_tipo, 'DESCONOCIDO'),
            len(sucursales_list),
        )
        
        return JsonResponse(sucursales_list, safe=False)
        
    except Exception as e:
        logger.exception("Error en obtener_sucursales")
        return JsonResponse({
            'success': False,
            'error': f'Error al obtener sucursales: {str(e)}'
        }, status=500)
def _bloquear_emision_dte(sucursal_id, tipo_doc):
    """Serializa las emisiones de un mismo tipo en la sucursal (lock de
    transacción de PostgreSQL; en otros motores no hace nada)."""
    from django.db import connection
    if connection.vendor != 'postgresql':
        return
    import hashlib
    digest = hashlib.blake2b(
        f'emitir_dte:{sucursal_id}:{tipo_doc}'.encode('utf-8'), digest_size=8,
    ).digest()
    with connection.cursor() as cursor:
        cursor.execute('SELECT pg_advisory_xact_lock(%s)',
                       [int.from_bytes(digest, 'big', signed=True)])


def _dte_emitido_duplicado(sucursal, tipo_doc, receptor, sucursal_destino,
                           responsable, detalle_productos, minutos=15):
    """DTE idéntico que este usuario emitió hace menos de `minutos`, o None.

    Idéntico = misma sucursal, tipo, receptor, destino y el mismo detalle
    (talla, cantidad, precio). Dte no guarda hora de creación: la ventana se
    mide con el movimiento de salida que escribe la emisión (fecha/hora de
    creación del kardex).
    """
    from datetime import timedelta
    try:
        pedido = sorted(
            (int(item.get('talla_id')), int(item.get('cantidad', 0)),
             int(float(item.get('precio', 0))))
            for item in detalle_productos
        )
    except (TypeError, ValueError):
        return None
    ahora = timezone.localtime()
    desde = ahora - timedelta(minutes=minutos)
    movimientos = Movimientos_Producto.objects.filter(
        dte__sucursal=sucursal,
        dte__tipo_documento=tipo_doc,
        dte__receptor=receptor,
        dte__responsable=responsable,
        dte__descartado=False,
        concepto__in=('VENTA_MAYORISTA', 'VENTA_PUBLICO', 'TRASPASO_SALIDA'),
        fecha=ahora.date(),
    ).exclude(dte__estado_dte='ANULADO')
    if desde.date() == ahora.date():
        movimientos = movimientos.filter(hora__gte=desde.time())
    if sucursal_destino is not None:
        movimientos = movimientos.filter(sucursal_destino=sucursal_destino)
    candidatos = (
        movimientos.order_by('-dte_id').values_list('dte_id', flat=True).distinct()[:10]
    )
    for dte_id in candidatos:
        lineas = sorted(
            (dp.productoTalla_id, int(dp.stock or 0), int(dp.precio or 0))
            for dp in Dte_Productos.objects.filter(dte_id=dte_id)
        )
        if lineas == pedido:
            return Dte.objects.get(id=dte_id)
    return None


@require_POST
@login_required
def emitir_dte(request):
    """
    Procesar la emisión de un DTE
    """
    try:
        data = json.loads(request.body)
        
        logger.debug("Datos recibidos en emitir_dte: %s", data)
        
        # Validar datos requeridos
        metodo_despacho = data.get('metodo_despacho')
        tipo_documento = data.get('tipo_documento')
        receptor_id = data.get('receptor_id')
        sucursal_destino_id = data.get('sucursal_destino_id')
        fecha_emision = data.get('fecha_emision')
        detalle_productos = data.get('detalle_productos', [])
        observaciones = data.get('observaciones', '')
        forma_pago_str = data.get('forma_pago', 'Contado')   # 'Contado' o 'Credito'
        dias_credito = int(data.get('dias_credito', 0) or 0)
        tipo_precio_externo = data.get('tipo_precio_externo')
        porcentaje_custom_raw = data.get('porcentaje_custom')
        # Referencia comercial opcional (Orden de Compra 801 / Nota de Pedido 802)
        referencia_tipo = (data.get('referencia_tipo') or '').strip() or None
        referencia_folio = (data.get('referencia_folio') or '').strip() or None
        referencia_fecha = data.get('referencia_fecha') or None
        from decimal import Decimal, InvalidOperation
        porcentaje_custom = None
        if porcentaje_custom_raw is not None:
            try:
                porcentaje_custom = Decimal(str(porcentaje_custom_raw))
            except (InvalidOperation, ValueError):
                porcentaje_custom = None
        
        logger.debug(
            "Campos emitir_dte: metodo=%s tipo=%s receptor_id=%s sucursal_destino_id=%s fecha=%s observaciones_len=%s items=%s",
            metodo_despacho,
            tipo_documento,
            receptor_id,
            sucursal_destino_id,
            fecha_emision,
            len(str(observaciones)) if observaciones else 0,
            len(detalle_productos),
        )
        
        # Validar datos básicos
        if not all([metodo_despacho, tipo_documento, fecha_emision]):
            return JsonResponse({
                'success': False,
                'error': 'Faltan datos obligatorios básicos'
            }, status=400)
        
        # Validar según tipo de despacho
        if metodo_despacho == 'interno':
            if not sucursal_destino_id:
                return JsonResponse({
                    'success': False,
                    'error': 'Debe seleccionar una sucursal destino para despacho interno'
                }, status=400)
        else:  # despacho externo
            if not receptor_id:
                return JsonResponse({
                    'success': False,
                    'error': 'Debe seleccionar una empresa cliente para despacho externo'
                }, status=400)
        
        if not detalle_productos:
            return JsonResponse({
                'success': False,
                'error': 'Debe incluir al menos un producto'
            }, status=400)
        
        # Obtener datos de sesión
        sucursal_id = request.session.get('idSucursalActual')
        empresa_id = request.session.get('idEmpresaActual')
        
        if not sucursal_id or not empresa_id:
            return JsonResponse({
                'success': False,
                'error': 'No hay sucursal activa en la sesión. Selecciona una sucursal antes de emitir.'
            }, status=400)
        
        # Obtener objetos según tipo de despacho
        emisor = get_object_or_404(Empresa, id=empresa_id)
        sucursal = get_object_or_404(Sucursal, id=sucursal_id)
        receptor = None
        sucursal_destino = None
        
        if metodo_despacho == 'interno':
            # Despacho interno: obtener sucursal destino y su empresa como receptor
            sucursal_destino = get_object_or_404(Sucursal, id=sucursal_destino_id)
            receptor = sucursal_destino.empresa  # La empresa se deduce de la sucursal
            
            # VALIDACIÓN IMPORTANTE: Verificar que los RUTs sean diferentes SOLO para FACTURAS
            # Para GUÍAS, se permite el mismo RUT (traspasos internos)
            if tipo_documento == 'FACTURA ELECTRONICA' and emisor.rut == receptor.rut:
                logger.warning("Intento de emitir factura interna con mismo RUT: rut=%s", emisor.rut)
                return JsonResponse({
                    'success': False,
                    'error': f'No se puede emitir FACTURA entre sucursales de empresas con el mismo RUT ({emisor.rut}). Use GUÍA DE DESPACHO para traspasos internos.'
                }, status=400)
            
            if emisor.rut != receptor.rut:
                logger.debug("Validacion RUT despacho interno OK: emisor=%s receptor=%s", emisor.rut, receptor.rut)
            else:
                logger.debug("Guia interna permitida con mismo RUT: rut=%s", emisor.rut)
        else:
            # Despacho externo: obtener empresa cliente
            receptor = get_object_or_404(Empresa, id=receptor_id)
        
        # El frontend ya envía los valores correctos del modelo, no necesitamos mapear
        tipo_doc = tipo_documento
        
        logger.debug("Tipo documento recibido en emitir_dte: tipo=%s", tipo_documento)
        
        # Validar que el tipo de documento sea válido
        tipos_validos = ['FACTURA ELECTRONICA', 'BOLETA ELECTRONICA', 'GUIA', 'NOTA DE PEDIDO', 'NOTA DE CREDITO']
        if tipo_doc not in tipos_validos:
            logger.warning("Tipo de documento invalido en emitir_dte: tipo=%s", tipo_doc)
            return JsonResponse({
                'success': False,
                'error': f'Tipo de documento inválido: {tipo_doc}. Valores válidos: {tipos_validos}'
            }, status=400)

        # NC con productos por esta ruta DESCONTABA stock como si fuera una
        # venta (la pantalla no la ofrece; solo un POST directo). Las NC van
        # por Gestión DTE → Nota de Crédito, que devuelve el stock.
        if tipo_doc == 'NOTA DE CREDITO':
            return JsonResponse({
                'success': False,
                'error': (
                    'Las Notas de Crédito no se emiten desde aquí: use Gestión DTE → '
                    'Nota de Crédito sobre el documento original (devuelve el stock), '
                    'o la emisión por concepto si no hay productos.'
                ),
            }, status=400)

        logger.debug("Tipo de documento validado en emitir_dte: tipo=%s", tipo_doc)

        # Facturas y guías generan TXT Acepta. No permitir que se emita un
        # documento que luego saldrá sin dirección/comuna/ciudad.
        if tipo_doc in ('FACTURA ELECTRONICA', 'GUIA'):
            emisor_direccion = (sucursal.direccion or emisor.direccion or '').strip()
            emisor_comuna = (getattr(sucursal, 'comuna', '') or emisor.comuna or '').strip()
            emisor_ciudad = (getattr(sucursal, 'ciudad', '') or emisor.ciudad or '').strip()
            if not all([emisor_direccion, emisor_comuna, emisor_ciudad]):
                return JsonResponse({
                    'success': False,
                    'error': (
                        'Faltan datos territoriales del emisor/sucursal para TXT Acepta: '
                        'dirección, comuna y ciudad son obligatorios.'
                    )
                }, status=400)

            receptor_direccion = (
                (sucursal_destino.direccion if sucursal_destino else '') or
                (receptor.direccion if receptor else '') or ''
            ).strip()
            receptor_comuna = (
                (getattr(sucursal_destino, 'comuna', '') if sucursal_destino else '') or
                (receptor.comuna if receptor else '') or ''
            ).strip()
            receptor_ciudad = (
                (getattr(sucursal_destino, 'ciudad', '') if sucursal_destino else '') or
                (receptor.ciudad if receptor else '') or ''
            ).strip()
            receptor_giro = (receptor.giro if receptor else '').strip()
            if not all([receptor_direccion, receptor_comuna, receptor_ciudad, receptor_giro]):
                return JsonResponse({
                    'success': False,
                    'error': (
                        f'Faltan datos del receptor para TXT Acepta ({receptor.nombre if receptor else "sin receptor"}): '
                        'giro, dirección, comuna y ciudad son obligatorios. '
                        'Completa la ficha de empresa/sucursal antes de emitir.'
                    )
                }, status=400)
        
        with transaction.atomic():
            logger.debug("Iniciando transaccion emitir_dte")
            # Reenvío del mismo formulario (doble clic, o reintento tras un
            # "Error de conexión" cuando el primer POST sí alcanzó a emitir):
            # creaba una segunda factura y descontaba el stock otra vez
            # (#16940 y #16941, stock 18 → 16 → 14). Se serializan las
            # emisiones de la sucursal+tipo y, si hay un DTE idéntico recién
            # emitido, se devuelve ese salvo confirmación explícita.
            _bloquear_emision_dte(sucursal.id, tipo_doc)
            if not data.get('confirmar_duplicado'):
                _dup = _dte_emitido_duplicado(
                    sucursal, tipo_doc, receptor, sucursal_destino,
                    request.user.username, detalle_productos,
                )
                if _dup is not None:
                    _lineas_dup = _dup.dte_productos.count()
                    _unidades_dup = _dup.dte_productos.aggregate(u=Sum('stock'))['u'] or 0
                    return JsonResponse({
                        'success': False,
                        'duplicado': True,
                        'dte_id': _dup.id,
                        'numero_documento': _dup.numero_documento,
                        'lineas_creadas': _lineas_dup,
                        'unidades': int(_unidades_dup),
                        'error': (
                            f'Hace unos minutos ya se emitió {_dup.tipo_documento} '
                            f'N° {_dup.numero_documento} con el mismo destino y el mismo '
                            'detalle. Volver a emitir descontaría el stock otra vez.'
                        ),
                    }, status=409)
            # Calcular totales
            subtotal_neto = 0
            total_unidades = 0
            
            logger.debug("Procesando productos para emitir_dte: total=%s", len(detalle_productos))
            tallas_vistas = set()
            for idx, item in enumerate(detalle_productos, 1):
                talla_id = item.get('talla_id')
                cantidad = int(item.get('cantidad', 0))
                precio = int(float(item.get('precio', 0)))  # Convertir a int para compatibilidad con IntegerField

                logger.debug("Item emitir_dte: idx=%s talla_id=%s cantidad=%s precio=%s", idx, talla_id, cantidad, precio)

                # Sin esta guarda, una cantidad negativa pasaba la validación de
                # stock (disponible < negativo es falso) y el descuento
                # `stock - cantidad` terminaba INFLANDO el stock del origen,
                # además de dejar un EGRESO con cantidad positiva en el kardex.
                if cantidad <= 0:
                    return JsonResponse({
                        'success': False,
                        'error': f'La cantidad de la línea {idx} debe ser mayor a 0.',
                    }, status=400)

                # Una misma talla repetida en el detalle validaba stock por
                # línea pero descontaba la suma: se consolida el envío.
                if talla_id in tallas_vistas:
                    return JsonResponse({
                        'success': False,
                        'error': (
                            'Hay una talla repetida en el detalle. '
                            'Agrupa las cantidades en una sola línea.'
                        ),
                    }, status=400)
                tallas_vistas.add(talla_id)


                # Validar stock disponible en la sucursal de origen
                talla = get_object_or_404(Producto_Talla, id=talla_id)
                
                # Verificar si tiene movimientos
                tiene_movimientos = talla.movimientos_productos_talla.exists()
                
                # ✅ Usar stock_sucursal() para validar stock específico de la sucursal origen
                stock_disponible = talla.stock_sucursal(sucursal_id)
                logger.debug(
                    "Stock item emitir_dte: producto=%s sku=%s talla=%s stock_global=%s producto_sucursal_id=%s sucursal_origen=%s tiene_movimientos=%s stock_disponible=%s",
                    talla.producto.articulo,
                    talla.sku,
                    talla.talla,
                    talla.stock,
                    talla.producto.sucursal_id,
                    sucursal_id,
                    tiene_movimientos,
                    stock_disponible,
                )
                
                if stock_disponible < cantidad:
                    logger.warning(
                        "Stock insuficiente en emitir_dte: sucursal=%s sku=%s solicitado=%s disponible=%s stock_global=%s tiene_movimientos=%s producto_sucursal_id=%s",
                        sucursal.alias,
                        talla.sku,
                        cantidad,
                        stock_disponible,
                        talla.stock,
                        tiene_movimientos,
                        talla.producto.sucursal_id,
                    )
                    
                    error_msg = f'Stock insuficiente para {talla.producto.articulo} talla {talla.talla} (SKU: {talla.sku}) en sucursal {sucursal.alias}. Disponible: {stock_disponible}, Solicitado: {cantidad}'
                    
                    if not tiene_movimientos and talla.producto.sucursal_id != sucursal_id:
                        error_msg += f'. NOTA: Este producto pertenece a otra sucursal (ID: {talla.producto.sucursal_id}). Necesita crear movimientos de traspaso o migrar a sistema de movimientos.'
                    
                    return JsonResponse({
                        'success': False,
                        'error': error_msg
                    }, status=400)
                
                subtotal_neto += cantidad * precio
                total_unidades += cantidad
            
            logger.debug("Validacion de stock OK para emitir_dte: subtotal=%s unidades=%s", subtotal_neto, total_unidades)
            
            # Calcular IVA y total. El IVA se redondea a peso entero (half-up,
            # igual que Math.round del front): sin esto el DTE quedaba con
            # decimales (neto 28.740 → 34.200,60) y las NC posteriores, que sí
            # redondean, "excedían" el saldo por fracciones de peso.
            subtotal_decimal = Decimal(str(subtotal_neto))
            iva = (subtotal_decimal * Decimal('0.19')).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
            total_con_iva = subtotal_decimal + iva
            logger.debug("Calculos emitir_dte: neto=%s iva=%s total=%s", subtotal_decimal, iva, total_con_iva)
            
            # Obtener correlativo oficial de la sucursal para este tipo de DTE
            try:
                numero_documento = obtener_siguiente_correlativo(sucursal, tipo_doc)
                logger.debug("Correlativo obtenido para emitir_dte: tipo=%s sucursal=%s numero=%s", tipo_doc, sucursal.alias, numero_documento)
            except Exception as correlativo_error:
                logger.exception("Error al obtener correlativo para emitir_dte")
                return JsonResponse({
                    'success': False,
                    'error': f'No fue posible obtener el correlativo para {tipo_doc}: {correlativo_error}'
                }, status=400)
            
            # Determinar estado y tipo según contexto de negocio
            if metodo_despacho == 'interno':
                estado_dte = 'EMITIDO'
                estado_pago = 'PENDIENTE'
                # TODOS los despachos internos son TRASPASO (factura o guía)
                tipo_transaccion = 'TRASPASO'
            else:
                # Despacho externo = Venta a cliente
                estado_dte = 'EMITIDO'
                estado_pago = 'PENDIENTE'
                tipo_transaccion = 'VENTA'
            
            logger.debug(
                "Logica emitir_dte: metodo=%s tipo_doc=%s estado_dte=%s estado_pago=%s tipo_transaccion=%s",
                metodo_despacho,
                tipo_doc,
                estado_dte,
                estado_pago,
                tipo_transaccion,
            )
            
            # Preparar referencias
            referencias_texto = f"Método despacho: {metodo_despacho}"
            if sucursal_destino:
                referencias_texto += f". Destino: {sucursal_destino.alias}"
            if observaciones:
                referencias_texto += f". {observaciones}"
            
            logger.debug(
                "Creando DTE: emisor_id=%s receptor_id=%s numero=%s tipo=%s estado_pago=%s estado_dte=%s tipo_transaccion=%s",
                emisor.id,
                receptor.id if receptor else None,
                numero_documento,
                tipo_doc,
                estado_pago,
                estado_dte,
                tipo_transaccion,
            )
            
            # Calcular fecha de vencimiento según forma de pago y días crédito
            from datetime import timedelta
            fecha_emision_date = parse_date(fecha_emision)
            es_credito = (forma_pago_str == 'Credito' and dias_credito > 0)
            fecha_vencimiento_date = (
                fecha_emision_date + timedelta(days=dias_credito)
                if es_credito else fecha_emision_date
            )
            dias_credito_final = dias_credito if es_credito else 0
            logger.debug("Pago emitir_dte: forma_pago=%s dias_credito=%s fecha_vencimiento=%s", forma_pago_str, dias_credito_final, fecha_vencimiento_date)
            
            # Crear DTE con todos los campos requeridos
            try:
                dte_kwargs = dict(
                    emisor=emisor,
                    receptor=receptor,
                    numero_documento=numero_documento,
                    tipo_documento=tipo_doc,
                    monto_neto=subtotal_decimal,
                    monto_con_iva=total_con_iva,
                    estado_pago=estado_pago,
                    estado_dte=estado_dte,
                    responsable=request.user.username,
                    fecha_emision=fecha_emision_date,
                    fecha_vencimiento=fecha_vencimiento_date,
                    diasCredito=dias_credito_final,
                    bultos=1,
                    unidades_productos=total_unidades,
                    tipo_transaccion=tipo_transaccion,
                    referencias=referencias_texto,
                    sucursal=sucursal,
                )
                if metodo_despacho == 'externo' and tipo_precio_externo:
                    tipo_map = {'costo': 'COSTO', 'sobreprecio': 'SOBREPRECIO', 'custom_pct': 'CUSTOM_PCT', 'precio_venta': 'PRECIO_VENTA'}
                    dte_kwargs['tipo_precio_externo'] = tipo_map.get(tipo_precio_externo, 'COSTO')
                    if tipo_precio_externo == 'custom_pct' and porcentaje_custom is not None:
                        dte_kwargs['porcentaje_custom'] = porcentaje_custom
                # Referencia comercial opcional (Orden de Compra 801 / Nota de Pedido 802)
                if referencia_tipo and referencia_folio:
                    dte_kwargs['referencia_tipo'] = referencia_tipo
                    dte_kwargs['referencia_folio'] = referencia_folio
                    dte_kwargs['referencia_fecha'] = parse_date(referencia_fecha) if referencia_fecha else None
                dte = Dte.objects.create(**dte_kwargs)
                logger.info("DTE emitido creado: dte_id=%s numero=%s tipo=%s", dte.id, numero_documento, tipo_doc)
            except Exception as e:
                logger.exception("Error al crear DTE en emitir_dte")
                return JsonResponse({
                    'success': False,
                    'error': f'Error al crear DTE: {str(e)}'
                }, status=400)
            
            # Crear detalle de productos y actualizar stock
            
            lineas_creadas = 0
            movimientos_creados = 0
            for item in detalle_productos:
                talla_id = item.get('talla_id')
                cantidad = int(item.get('cantidad', 0))
                precio = int(float(item.get('precio', 0)))  # Convertir a int para compatibilidad con IntegerField

                talla = Producto_Talla.objects.select_related('producto').get(id=talla_id)
                producto = talla.producto

                # ✅ VALIDACIÓN DEFENSIVA: el Producto_Talla elegido debe
                # pertenecer a la sucursal emisora del DTE. Si no lo es, el
                # stock se descontaría de otra sucursal y el ajuste posterior
                # (NC / AJUSTE) aplicaría a un inventario equivocado.
                # Este error indica un bug de integración en el frontend
                # (buscador que mezcla SKUs de distintas sucursales).
                if producto and producto.sucursal_id != sucursal.id:
                    logger.error(
                        "emitir_dte: Producto_Talla %s (SKU %s) pertenece a "
                        "sucursal %s pero se está emitiendo desde sucursal %s.",
                        talla.id, talla.sku, producto.sucursal_id, sucursal.id,
                    )
                    raise ValueError(
                        f'Producto SKU {talla.sku} no pertenece a la sucursal '
                        f'emisora ({sucursal.alias}). No se puede despachar un '
                        f'producto que pertenece a otra sucursal.'
                    )

                # Guardar sobreprecio tal cual está en el producto (es un DELTA/MARGEN)
                costo_unitario = producto.costo
                sobreprecio_unitario = producto.sobreprecio
                
                logger.debug(
                    "Detalle producto emitir_dte: producto_id=%s costo=%s sobreprecio=%s precio=%s",
                    producto.id,
                    costo_unitario,
                    sobreprecio_unitario,
                    precio,
                )
                
                # Crear detalle del DTE
                Dte_Productos.objects.create(
                    dte=dte,
                    productoTalla=talla,
                    descripcion=f"{producto.articulo} - Talla {talla.talla}",
                    costo=costo_unitario,
                    sobreprecio=sobreprecio_unitario,
                    precio=int(precio),
                    stock=cantidad,
                    activo=True
                )
                lineas_creadas += 1
                
                # Gestión de stock y movimientos según tipo de despacho
                if metodo_despacho == 'externo':
                    # DESPACHO EXTERNO: Crear movimiento de egreso (venta a cliente)
                    # Boleta = venta al público, Factura = venta mayorista
                    concepto_venta = 'VENTA_PUBLICO' if 'BOLETA' in tipo_doc else 'VENTA_MAYORISTA'
                    Movimientos_Producto.objects.create(
                        dte=dte,
                        ProductoTalla=talla,
                        sucursal_origen=sucursal,
                        sucursal_destino=None,
                        cantidad=-cantidad,  # Negativo porque es egreso
                        costo=producto.costo,
                        sobreprecio=producto.sobreprecio,
                        precio=int(precio),
                        concepto=concepto_venta,
                        tipo_movimiento='EGRESO',
                        estado='COMPLETADO',
                        responsable=request.user.username,
                        observaciones=f"Venta DTE #{numero_documento} - Cliente: {receptor.nombre if receptor else 'N/A'}"
                    )
                    movimientos_creados += 1
                    
                    # ✅ Actualizar stock legacy para mantener sincronización
                    Producto_Talla.objects.filter(id=talla.id).update(stock=F('stock') - cantidad)
                    # Consumir lotes FIFO junto con el stock plano; si la capa
                    # de lotes está incompleta no se bloquea la emisión (el
                    # faltante queda para reconciliar_stock_lotes).
                    try:
                        from app.services.inventario_service import consumir_lotes_fifo
                        consumir_lotes_fifo(talla, cantidad)
                    except Exception as e_lotes:
                        logger.warning(
                            "emitir_dte externo: lotes FIFO no consumidos sku=%s cantidad=%s: %s",
                            talla.sku, cantidad, e_lotes,
                        )
                    logger.info(
                        "Movimiento de egreso venta creado: sku=%s cantidad=%s sucursal=%s",
                        talla.sku,
                        cantidad,
                        sucursal.alias,
                    )
                    
                else:
                    # DESPACHO INTERNO: Crear movimiento de traspaso (salida en origen)
                    # ⚠️ IMPORTANTE: Solo se crea el movimiento de EGRESO en origen
                    # El movimiento de INGRESO en destino se creará cuando la sucursal destino recepcione
                    
                    Movimientos_Producto.objects.create(
                        dte=dte,
                        ProductoTalla=talla,
                        sucursal_origen=sucursal,
                        sucursal_destino=sucursal_destino,
                        cantidad=-cantidad,  # Negativo porque es egreso
                        costo=producto.costo,
                        sobreprecio=producto.sobreprecio,
                        precio=int(precio),
                        concepto='TRASPASO_SALIDA',
                        tipo_movimiento='EGRESO',
                        estado='COMPLETADO',  # ✅ COMPLETADO inmediatamente - el stock ya salió de origen
                        responsable=request.user.username,
                        observaciones=f"Traspaso DTE #{numero_documento} - Origen: {sucursal.alias} → Destino: {sucursal_destino.alias}"
                    )
                    movimientos_creados += 1
                    
                    # ✅ Actualizar stock legacy para mantener sincronización con movimientos
                    Producto_Talla.objects.filter(id=talla.id).update(stock=F('stock') - cantidad)
                    # Consumir lotes FIFO junto con el stock plano (misma
                    # política best-effort que el despacho externo).
                    try:
                        from app.services.inventario_service import consumir_lotes_fifo
                        consumir_lotes_fifo(talla, cantidad)
                    except Exception as e_lotes:
                        logger.warning(
                            "emitir_dte interno: lotes FIFO no consumidos sku=%s cantidad=%s: %s",
                            talla.sku, cantidad, e_lotes,
                        )
                    logger.info(
                        "Movimiento de egreso traspaso creado: sku=%s cantidad=%s origen=%s destino=%s",
                        talla.sku,
                        cantidad,
                        sucursal.alias,
                        sucursal_destino.alias,
                    )

            lineas_esperadas = len(detalle_productos)
            lineas_bd = Dte_Productos.objects.filter(dte=dte).count()
            movimientos_bd = Movimientos_Producto.objects.filter(dte=dte).count()
            if lineas_bd != lineas_esperadas or lineas_creadas != lineas_esperadas:
                raise ValueError(
                    f'Emisión incompleta: se esperaban {lineas_esperadas} línea(s), '
                    f'pero quedaron {lineas_bd} en el DTE. La transacción fue revertida.'
                )
            if movimientos_bd < lineas_esperadas or movimientos_creados < lineas_esperadas:
                raise ValueError(
                    f'Emisión incompleta: se esperaban al menos {lineas_esperadas} movimiento(s), '
                    f'pero quedaron {movimientos_bd}. La transacción fue revertida.'
                )

            # CC-08: la cola de PendienteDespacho (compra consolidada en el CD
            # → "hay que mandar X a la tienda Y") se descuenta en ESTA
            # transacción, junto con los TRASPASO_SALIDA recién creados. El
            # POST posterior de emisionDTE a consumir_pendientes_despacho
            # quedó idempotente y ya no descuenta dos veces.
            pendientes_consumidos = []
            if metodo_despacho == 'interno' and sucursal_destino is not None:
                pendientes_consumidos = _consumir_pendientes_por_despacho(
                    sucursal_destino.id,
                    [int(item.get('talla_id')) for item in detalle_productos],
                )

        return JsonResponse({
            'success': True,
            'message': 'DTE emitido correctamente',
            'numero_documento': numero_documento,
            'dte_id': dte.id,
            'total': float(total_con_iva),
            'lineas_recibidas': len(detalle_productos),
            'lineas_creadas': lineas_bd,
            'movimientos_creados': movimientos_bd,
            'unidades': total_unidades,
            'pendientes_despacho_consumidos': pendientes_consumidos,
        })
        
    except json.JSONDecodeError:
        return JsonResponse({
            'success': False,
            'error': 'Datos JSON inválidos'
        }, status=400)
    except ValueError as ve:
        # Errores de validación semántica (p.ej. SKU de otra sucursal).
        return JsonResponse({
            'success': False,
            'error': str(ve),
        }, status=400)
    except Exception as e:
        return JsonResponse({
            'success': False,
            'error': f'Error al emitir DTE: {str(e)}'
        }, status=500)

