@login_required
@_api_requiere_alguno(
    ('recepcion_dte', 'puede_ver'), mensaje=MSG_SIN_PERMISO_AVISOS_DTE,
    vacio={'total_pendientes': 0, 'monto_total': 0, 'dtes': []},
)
@require_GET
def obtener_dtes_pendientes_recibir(request):
    """
    Obtiene los DTEs pendientes de recibir para la empresa actual.
    Usado para el badge de notificaciones y la lista del dashboard.
    Solo muestra DTEs de traspaso pendientes de recepción para la sucursal actual.
    """
    try:
        empresa_id = request.session.get('idEmpresaActual')
        sucursal_destino_id = request.session.get('idSucursalActual')
        usuario_id = request.user.id

        if not empresa_id or not sucursal_destino_id:
            return JsonResponse({
                'success': False,
                'error': 'No hay empresa o sucursal seleccionada'
            })

        # DTEs de traspaso pendientes de recepción en la sucursal actual
        dtes_query = (
            Dte.objects.select_related('emisor', 'receptor', 'sucursal')
            .filter(
                tipo_transaccion='TRASPASO',
                estado_dte='EMITIDO',
                dte_movimientos__concepto='TRASPASO_SALIDA',
                dte_movimientos__tipo_movimiento='EGRESO',
                dte_movimientos__estado='COMPLETADO',
                dte_movimientos__sucursal_destino_id=sucursal_destino_id
            )
            .distinct()
            .order_by('-fecha_emision')
        )
        try:
            from django.db.utils import OperationalError, ProgrammingError

            dtes_query = dtes_query.exclude(alertas_descartadas__usuario_id=usuario_id)
        except (OperationalError, ProgrammingError):
            # Tabla de descartes no disponible (migración pendiente)
            pass
        
        total = dtes_query.count()
        monto_total = dtes_query.aggregate(
            total=Sum('monto_con_iva')
        )['total'] or 0
        
        # Lista de DTEs (máximo 20)
        lista_dtes = []
        for dte in dtes_query[:20]:
            hoy = timezone.localdate()
            dias_desde_emision = (hoy - dte.fecha_emision).days if dte.fecha_emision else 0
            
            lista_dtes.append({
                'id': dte.id,
                'numero_documento': dte.numero_documento,
                'tipo_documento': dte.tipo_documento,
                'emisor_nombre': dte.emisor.nombre if dte.emisor else 'Desconocido',
                'emisor_rut': dte.emisor.rut if dte.emisor else '',
                'sucursal_origen_alias': dte.sucursal.alias if dte.sucursal else '-',
                'monto_con_iva': float(dte.monto_con_iva),
                'fecha_emision': dte.fecha_emision.strftime('%d/%m/%Y') if dte.fecha_emision else '',
                'dias_desde_emision': dias_desde_emision,
                'unidades_productos': dte.unidades_productos,
                'bultos': dte.bultos,
                'urgente': dias_desde_emision > 7,
            })
        
        return JsonResponse({
            'success': True,
            'total_pendientes': total,
            'monto_total': float(monto_total),
            'dtes': lista_dtes
        })

    except Exception:
        logger.exception("Error en obtener_dtes_pendientes_recibir")
        return JsonResponse({
            'success': False,
            'error': 'No se pudieron cargar los DTE pendientes de recibir.'
        })


@login_required
@_api_requiere_alguno(('recepcion_dte', 'puede_ver'), mensaje=MSG_SIN_PERMISO_AVISOS_DTE)
@require_POST
def descartar_dte_pendiente(request):
    """Descarta una alerta de DTE pendiente para el usuario actual."""
    import json
    from .models import DteAlertaDescartada
    from django.db.utils import OperationalError, ProgrammingError

    try:
        data = json.loads(request.body)
        dte_id = data.get('dte_id')

        if not dte_id:
            return JsonResponse({
                'success': False,
                'error': 'ID de DTE requerido'
            }, status=400)

        sucursal_destino_id = request.session.get('idSucursalActual')
        if not sucursal_destino_id:
            return JsonResponse({
                'success': False,
                'error': 'No hay sucursal seleccionada'
            }, status=400)

        dte = Dte.objects.filter(
            id=dte_id,
            tipo_transaccion='TRASPASO',
            estado_dte='EMITIDO',
            dte_movimientos__concepto='TRASPASO_SALIDA',
            dte_movimientos__tipo_movimiento='EGRESO',
            dte_movimientos__estado='COMPLETADO',
            dte_movimientos__sucursal_destino_id=sucursal_destino_id
        ).first()

        if not dte:
            return JsonResponse({
                'success': False,
                'error': 'DTE no encontrado o no pendiente de recepción'
            }, status=404)

        try:
            DteAlertaDescartada.objects.get_or_create(
                dte=dte,
                usuario=request.user,
                defaults={'sucursal_id': sucursal_destino_id}
            )
        except (OperationalError, ProgrammingError):
            logger.exception(
                'descartar_dte_pendiente: DteAlertaDescartada no disponible'
            )
            return JsonResponse({
                'success': False,
                'error': 'No se pudo descartar el aviso del DTE.'
            }, status=500)

        return JsonResponse({
            'success': True
        })

    except Exception:
        logger.exception("Error en descartar_dte_pendiente")
        return JsonResponse({
            'success': False,
            'error': 'No se pudo descartar el aviso del DTE.'
        }, status=500)


@login_required
@_api_requiere_alguno(
    ('recepcion_dte', 'puede_ver'), mensaje=MSG_SIN_PERMISO_AVISOS_DTE,
    vacio={'total_pendientes': 0, 'dtes': []},
)
@require_GET
def obtener_dtes_pendientes_regularizar(request):
    """
    Obtiene los DTEs pendientes de regularización para la sucursal emisora.
    Usado para mostrar notificaciones en el navbar a la bodega que emitió el traspaso.

    Acepta ?alcance=todas para usuarios con permiso multi-sucursal, en cuyo
    caso devuelve los DTEs emitidos por cualquier sucursal del usuario, no
    solo la sucursal activa.
    """
    try:
        sucursal_id = request.session.get('idSucursalActual')
        puede_ver_todas = (
            request.user.is_superuser
            or PermisoUsuario.usuario_ve_todas_sucursales(request.user)
        )
        ver_todas = puede_ver_todas and request.GET.get('alcance') == 'todas'

        if not sucursal_id and not ver_todas:
            return JsonResponse({
                'success': False,
                'error': 'No hay sucursal seleccionada'
            })

        # DTEs emitidos por esta sucursal (o por cualquiera si ver_todas) con
        # problemas de recepción.
        filtro_sucursal = Q() if ver_todas else Q(sucursal_id=sucursal_id)
        dtes_query = Dte.objects.select_related(
            'emisor', 'receptor', 'sucursal'
        ).filter(
            filtro_sucursal,
            tipo_transaccion='TRASPASO',
            estado_dte__in=['RECEPCIONADO_PARCIAL', 'EN_REGULARIZACION']
        ).annotate(
            productos_con_problemas=Count(
                'recepciones',
                filter=Q(recepciones__estado__in=['EN_REGULARIZACION', 'FALTANTE', 'RECEPCIONADO_PARCIAL', 'RECEPCIONADO_DANADO'])
            )
        ).filter(
            productos_con_problemas__gt=0
        ).order_by('-fecha_recepcion')
        
        total = dtes_query.count()
        
        # Lista de DTEs (máximo 20)
        lista_dtes = []
        # Este endpoint alimenta la campana del navbar, así que se dispara en toda
        # la navegación. Leer el destino dentro del bucle costaba 2 consultas por
        # DTE (~41 por página); con el Prefetch queda en 2 en total.
        from django.db.models import Prefetch
        pagina_dtes = list(
            dtes_query[:20].prefetch_related(
                Prefetch(
                    'dte_movimientos',
                    queryset=Movimientos_Producto.objects.filter(
                        concepto='TRASPASO_SALIDA'
                    ).select_related('sucursal_destino'),
                    to_attr='salidas_traspaso',
                )
            )
        )
        hoy = timezone.localdate()
        for dte in pagina_dtes:
            dias_desde_recepcion = (hoy - dte.fecha_recepcion).days if dte.fecha_recepcion else 0

            # Obtener destino del traspaso
            salidas = getattr(dte, 'salidas_traspaso', None) or []
            movimiento = salidas[0] if salidas else None
            destino_alias = movimiento.sucursal_destino.alias if movimiento and movimiento.sucursal_destino else 'Desconocido'

            lista_dtes.append({
                'id': dte.id,
                'numero_documento': dte.numero_documento,
                'tipo_documento': dte.tipo_documento,
                'destino_nombre': destino_alias,
                'fecha_recepcion': dte.fecha_recepcion.strftime('%d/%m/%Y') if dte.fecha_recepcion else '',
                'dias_pendiente': dias_desde_recepcion,
                'productos_problema': dte.productos_con_problemas,
                'urgente': dias_desde_recepcion > 3,
            })
        
        return JsonResponse({
            'success': True,
            'total_pendientes': total,
            'dtes': lista_dtes
        })

    except Exception:
        logger.exception("Error en obtener_dtes_pendientes_regularizar")
        return JsonResponse({
            'success': False,
            'error': 'No se pudieron cargar los DTE pendientes de regularizar.'
        })


